<div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><h1 class="iss-title h2 mb-2"><?= htmlspecialchars($pageTitle) ?></h1><p class="text-muted mb-0"><?= htmlspecialchars($pageCopy) ?></p></div><a class="btn btn-outline-secondary" href="<?= htmlspecialchars($settingsOverviewUrl) ?>"><i class="fa-solid fa-arrow-left me-2"></i>Settings Overview</a></div><hr class="mt-3 mb-4">
