<?php if($issuanceSection==='general'):?><form method="post" class="iss-panel"><input type="hidden" name="action" value="save_issuance_section"><?= csrfTokenField() ?><div class="iss-head"><h2 class="h5 mb-1">Issuance controls</h2><p class="small text-muted mb-0">These rules apply to all supported certificate requests.</p></div><div class="iss-body"><div class="iss-grid">
<?php foreach([['online_requests_enabled','Enable online certificate requests','Residents can submit certificate applications online.'],['first_time_job_seeker_exempt','First-Time Job Seeker fee exemption','Apply the configured exemption to eligible requests.'],['qr_verification_enabled','Enable QR verification','Allow scans to verify certificates from this department. QR codes remain printed when disabled.'],['essential_details_only','Essential resident details only','Limit views to details required for processing.'],['copy_has_signature','Resident copy signature','Show the uploaded official signature on the resident certificate copy.'],['print_header_enabled','Add barangay header when printed','Turn off when using bond paper that already has the barangay letterhead.']] as [$key,$label,$copy]):?><label class="iss-option"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="<?= $key ?>" id="<?= $key ?>" <?= !empty($issuanceSettings[$key])?'checked':'' ?>><span class="fw-semibold ms-2"><?= htmlspecialchars($label) ?></span></div><div class="small text-muted ms-5"><?= htmlspecialchars($copy) ?></div></label><?php endforeach;?>
</div><hr><h3 class="h6 fw-bold">Generated document fields</h3><p class="small text-muted">Turn each field on or off on generated certificate documents and PDFs.</p><div class="iss-grid"><?php foreach(dms_document_field_catalog('issuance') as $fieldKey=>$fieldLabel):?><label class="iss-option"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="document_field_visible[<?= htmlspecialchars($fieldKey) ?>]" <?= !empty($issuanceSettings['document_field_visibility'][$fieldKey])?'checked':'' ?>><span class="fw-semibold ms-2">Show <?= htmlspecialchars($fieldLabel) ?></span></div></label><?php endforeach;?></div><hr><div class="row g-3"><div class="col-md-4"><label class="form-label fw-semibold">Default validity</label><div class="input-group"><input class="form-control" type="number" min="1" max="365" name="default_validity_days" value="<?= (int)$issuanceSettings['default_validity_days'] ?>"><span class="input-group-text">days</span></div></div><div class="col-md-8"><label class="form-label fw-semibold d-block">Allowed validity choices</label><div class="d-flex flex-wrap gap-3 pt-2"><?php foreach([3,7,15,30,45,60,90,180,365] as $days):?><label class="form-check"><input class="form-check-input" type="checkbox" name="allowed_validity_days[]" value="<?= $days ?>" <?= in_array($days,(array)$issuanceSettings['allowed_validity_days'],true)?'checked':'' ?>> <?= $days ?> days</label><?php endforeach;?></div></div></div><div class="text-end mt-4"><button class="btn btn-iss px-4">Save General Settings</button></div></div></form><?php endif;?>

<?php if($issuanceSection==='certificates'):?><form method="post" class="iss-panel"><input type="hidden" name="action" value="save_issuance_section"><?= csrfTokenField() ?><div class="iss-head"><h2 class="h5 mb-1">Certificate catalog</h2><p class="small text-muted mb-0">Enter one purpose option per line.</p></div><div class="iss-body"><div class="iss-cert-grid"><?php foreach(dms_issuance_certificate_catalog() as $key=>$label):$cert=$issuanceSettings['certificates'][$key]??[];?><section class="iss-cert"><div class="iss-cert-head"><strong><?= htmlspecialchars($label) ?></strong><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="certificate_enabled[<?= $key ?>]" <?= !empty($cert['enabled'])?'checked':'' ?>></div></div><div class="iss-cert-body"><label class="form-label small fw-semibold">Purpose options</label><textarea class="form-control" rows="6" name="purpose_options[<?= $key ?>]"><?= htmlspecialchars(implode("\n",(array)($cert['purpose_options']??[]))) ?></textarea></div></section><?php endforeach;?></div><div class="text-end mt-4"><button class="btn btn-iss px-4">Save Certificate Settings</button></div></div></form><?php endif;?>

<?php if($issuanceSection==='notifications'):?><form method="post" class="iss-panel"><input type="hidden" name="action" value="save_issuance_section"><?= csrfTokenField() ?><div class="iss-head"><h2 class="h5 mb-1">Resident messages</h2><p class="small text-muted mb-0">Placeholders: {request_id}, {document_type}, {reason}, {count}, {days}</p></div><div class="iss-body"><?php foreach((array)$issuanceSettings['resident_notifications'] as $event=>$notification):?><div class="iss-notice-row"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="notification_enabled[<?= $event ?>]" id="n_<?= $event ?>" <?= !empty($notification['enabled'])?'checked':'' ?>><label class="form-check-label fw-semibold text-capitalize" for="n_<?= $event ?>"><?= htmlspecialchars(str_replace('_',' ',$event)) ?></label></div><textarea class="form-control" rows="2" name="notification_message[<?= $event ?>]"><?= htmlspecialchars((string)$notification['message']) ?></textarea></div><?php endforeach;?><div class="iss-option mt-3"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="aging_notification_enabled" id="aging" <?= !empty($issuanceSettings['aging_notification_enabled'])?'checked':'' ?>><label class="form-check-label fw-semibold" for="aging">Aging-request notification</label></div><p class="small text-muted mb-3">Notify the employees responsible for certificate issuance when requests remain pending beyond the threshold.</p><div class="row g-3"><div class="col-md-3"><label class="form-label small fw-semibold">Threshold</label><div class="input-group"><input class="form-control" type="number" name="aging_days" min="1" max="90" value="<?= (int)$issuanceSettings['aging_days'] ?>"><span class="input-group-text">days</span></div></div><div class="col-md-9"><label class="form-label small fw-semibold">Message</label><textarea class="form-control" rows="2" name="aging_message"><?= htmlspecialchars((string)$issuanceSettings['aging_message']) ?></textarea></div><div class="col-12"><label class="form-label fw-semibold">Who should receive this notification?</label><select class="form-select" name="aging_recipient_mode" id="agingRecipientMode"><option value="module_access" <?= ($issuanceSettings['aging_recipient_mode']??'module_access')==='module_access'?'selected':'' ?>>All employees with Barangay Issuance access</option><option value="specific" <?= ($issuanceSettings['aging_recipient_mode']??'')==='specific'?'selected':'' ?>>Only selected employees</option></select><div class="form-text">Module access follows the employee permissions configured by the Super Admin.</div></div><div class="col-12" id="agingRecipientSelection"><label class="form-label small fw-semibold">Select employees</label><div class="iss-recipient-list"><?php if($notificationRecipientOptions===[]):?><div class="text-muted small">No eligible employee accounts found.</div><?php endif;?><?php foreach($notificationRecipientOptions as $recipient):$uid=(string)$recipient['user_id'];?><label class="iss-recipient"><span class="form-check"><input class="form-check-input" type="checkbox" name="aging_recipient_user_ids[]" value="<?= htmlspecialchars($uid) ?>" <?= in_array($uid,(array)($issuanceSettings['aging_recipient_user_ids']??[]),true)?'checked':'' ?>><span class="form-check-label"><strong><?= htmlspecialchars((string)$recipient['name']) ?></strong><small class="d-block text-muted"><?= htmlspecialchars(implode(' · ',array_filter([(string)$recipient['position'],(string)$recipient['department']]))) ?></small></span></span></label><?php endforeach;?></div></div></div></div><div class="text-end mt-4"><button class="btn btn-iss px-4">Save Notification Settings</button></div></div></form><?php endif;?>

<?php if($issuanceSection==='indigency'):?><section class="iss-panel"><div class="iss-head"><h2 class="h5 mb-1">Government officials</h2><p class="small text-muted mb-0">Records appear directly in the resident Indigency request dropdown.</p></div><div class="iss-body"><form method="post" class="iss-official-form mb-4"><input type="hidden" name="action" value="save_indigency_government_official"><input type="hidden" name="government_official_id" id="oid" value="0"><?= csrfTokenField() ?><div><label class="form-label small">Name</label><input class="form-control" name="official_name" id="oname" required></div><div><label class="form-label small">Position</label><input class="form-control" name="position_name" id="oposition" required></div><div><label class="form-label small">Office / Jurisdiction</label><input class="form-control" name="jurisdiction_location" id="olocation" required></div><div><label class="form-label small">Group</label><select class="form-select" name="group_key" id="ogroup"><option value="president">President</option><option value="vice_president">Vice President</option><option value="senate">Senate</option><option value="rizal_officials">Rizal Officials</option><option value="municipal_officials">Municipal Officials</option></select></div><div><label class="form-label small">Order</label><input class="form-control" type="number" name="display_order" id="oorder" value="0"></div><div><input type="hidden" name="is_active" value="1"><button class="btn btn-iss" id="osubmit">Add</button></div></form><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Name</th><th>Position</th><th>Office</th><th>Group</th><th>Order</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($governmentOfficialRows as $row):$id=(int)$row['government_official_id'];?><tr><td class="fw-semibold"><?= htmlspecialchars((string)$row['official_name']) ?></td><td><?= htmlspecialchars((string)$row['position_name']) ?></td><td><?= htmlspecialchars((string)$row['jurisdiction_location']) ?></td><td><?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$row['group_key']))) ?></td><td><?= (int)$row['display_order'] ?></td><td><?= !empty($row['is_active'])?'<span class="badge text-bg-success">Active</span>':'<span class="badge text-bg-secondary">Inactive</span>' ?></td><td class="text-end"><button type="button" class="btn btn-sm btn-outline-primary" data-edit-official data-id="<?= $id ?>" data-name="<?= htmlspecialchars((string)$row['official_name'],ENT_QUOTES) ?>" data-position="<?= htmlspecialchars((string)$row['position_name'],ENT_QUOTES) ?>" data-location="<?= htmlspecialchars((string)$row['jurisdiction_location'],ENT_QUOTES) ?>" data-group="<?= htmlspecialchars((string)$row['group_key'],ENT_QUOTES) ?>" data-order="<?= (int)$row['display_order'] ?>"><i class="fa-solid fa-pen"></i></button><form method="post" class="d-inline" onsubmit="return confirm('Delete this official?')"><?= csrfTokenField() ?><input type="hidden" name="action" value="delete_indigency_government_official"><input type="hidden" name="government_official_id" value="<?= $id ?>"><button class="btn btn-sm btn-outline-danger"><i class="fa-solid fa-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php endif;?>

<?php if($issuanceSection==='fees'):?><section class="iss-panel"><div class="iss-head"><h2 class="h5 mb-1">Certificate fee management</h2><p class="small text-muted mb-0">Fee changes use an approval workflow and are audit logged.</p></div><div class="iss-body"><div class="iss-grid"><div class="iss-option"><h3 class="h6 fw-bold">Request a fee change</h3><p class="small text-muted">Review the current certificate catalog and propose an updated amount.</p><a class="btn btn-iss" href="<?= htmlspecialchars(appUrl('Admin-End/Certificates/CertificateTracker.php?tab=fees&fee_scope=issuance&filter_document=__certificates__')) ?>">Open Fee Catalog</a></div><div class="iss-option"><h3 class="h6 fw-bold">Submitted requests</h3><p class="small text-muted">Review pending, approved, rejected, or cancelled fee requests.</p><a class="btn btn-outline-secondary" href="<?= htmlspecialchars(appUrl('Admin-End/Certificates/CertificateTracker.php?tab=fees&fee_scope=issuance&filter_document=__certificates__&fee_view=requests')) ?>">View Submitted Requests</a></div></div></div></section><?php endif;?>
</div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><?php if($issuanceSection==='notifications'):?><script>(()=>{const mode=document.getElementById('agingRecipientMode'),selection=document.getElementById('agingRecipientSelection');const sync=()=>selection?.classList.toggle('d-none',mode?.value!=='specific');mode?.addEventListener('change',sync);sync();})();</script><?php endif;?><?php if($issuanceSection==='indigency'):?><script>document.querySelectorAll('[data-edit-official]').forEach(b=>b.addEventListener('click',()=>{oid.value=b.dataset.id;oname.value=b.dataset.name;oposition.value=b.dataset.position;olocation.value=b.dataset.location;ogroup.value=b.dataset.group;oorder.value=b.dataset.order;osubmit.textContent='Update';oname.focus();}));</script><?php endif;?></body></html>
